body:
{
  "pains": [
    {
      "id": "pain:tax-filing-errors",
      "statement": "I pay payroll software to file my taxes, then a notice shows up for something it filed wrong, and I am the one stuck fixing it and paying the penalty.",
      "element": "b2b:table_stakes:regulatory_compliance",
      "shape": {
        "surface": "An IRS or state notice (941, state unemployment, L&I, W-2 mismatch) arrives for a filing the payroll provider was paid to handle.",
        "operational": "The owner or bookkeeper has to find the error, upload the notice, chase the provider's tax team for weeks, and often pay the agency directly while the case sits open.",
        "personal": "Real money out of pocket (one owner absorbed about $3,000, another paid a $1,000 fee) plus the feeling that nobody is keeping them compliant: 'now I have NO confidence in their ability to keep me compliant.'"
      },
      "workflow": "After payroll runs in Gusto and Gusto files the 941, state UI or L&I return, a notice comes in the mail weeks or months later; the admin uploads it in Gusto for the Tax team, then waits on chat or email while penalties and interest keep adding up.",
      "type": "felt",
      "confidence": "high",
      "priority": 1,
      "felt_evidence": {
        "kind": "paying",
        "what": "Owners are paying the agencies themselves to make it stop: one paid a $1,000 fee 'to get the state off my back' after a state move Gusto mishandled, another absorbed about a $3,000 tax bill, a third is going outside Gusto to fix W-2s.",
        "cites": ["src:4", "src:1", "src:7"]
      },
      "revealed_by": null,
      "triggers": [
        {"event": "An IRS or state notice arrives for a late or missing payroll tax payment the owner thought was filed.", "cites": ["src:1", "src:2", "src:5"]},
        {"event": "Year-end W-2s do not match the year's 941 totals.", "cites": ["src:7"]},
        {"event": "Switching payroll providers mid-year.", "cites": ["src:1"]},
        {"event": "Quarterly state filings (L&I, TWC) go in wrong or not at all.", "cites": ["src:6", "src:20"]}
      ],
      "who_feels": ["economic_buyer", "champion"],
      "by_role": {
        "economic_buyer": {
          "says": [
            {"situation": "venting", "verbatim": "If Gusto makes a mistake then the onus is on you to correct the problem.", "cites": ["src:2"]},
            {"situation": "when_it_bites", "verbatim": "We ultimately had to absorb approximately a $3,000 tax bill.", "cites": ["src:1"]},
            {"situation": "when_it_bites", "verbatim": "Takes weeks for them to respond to requests to fix issues when I get notices.", "cites": ["src:3"]},
            {"situation": "when_refusing", "verbatim": "We have now had two significant tax issues while using Gusto, and there will not be a third.", "cites": ["src:1"]},
            {"situation": "venting", "verbatim": "Have had 2 major tax issues in less than a year.", "cites": ["src:30"]},
            {"situation": "when_it_bites", "verbatim": "Gusto had not communicated anything to me but I figured as a 941 was referenced it had to be them.", "cites": ["src:5"]}
          ],
          "costs_them": "Penalties and interest they did not cause, hours of chat and email, and in some cases paying the agency directly before the provider resolves anything.",
          "fears": "Collections, a lien, or a state account frozen over a filing they never touched; being personally on the hook for trust-fund taxes.",
          "dream_outcome": "Never open a tax notice again, and if one does come, the provider owns it end to end and pays what its error cost."
        },
        "champion": {
          "says": [
            {"situation": "venting", "verbatim": "Incorrect Q1 LNI filings with ALL the companies I manage, even after notifying them of issues before quarter ended.", "cites": ["src:6"]},
            {"situation": "when_it_bites", "verbatim": "13 pages of email, and whited out W-2c copies showing exactly what the changes need to look like.", "cites": ["src:7"]},
            {"situation": "when_refusing", "verbatim": "I did a better job with pencil and paper. Now I need a lawyer", "cites": ["src:6"]}
          ],
          "costs_them": "The bookkeeper or office manager does the provider's correction work by hand and answers to the owner for a mistake they did not make.",
          "fears": "Looking incompetent to the owner or client when the notice lands on their desk.",
          "dream_outcome": "Filings that are right the first time, so their own name is never attached to a penalty."
        }
      },
      "relief": {
        "line": "Notice handled for me. A tax letter comes in and the provider's tax team clears it without my input.",
        "says": [
          {"role": "economic_buyer", "verbatim": "their tax team took care of it fairly easily with minimal input from me.", "cites": ["src:5"]}
        ],
        "gap": null
      },
      "euphoria": {
        "line": "I stopped thinking about payroll taxes. A year on, compliance is something that just happens in the background.",
        "says": [],
        "gap": "Searched Trustpilot positive reviews (Cheryl Rose, BioOpt Health, brenda dye) and PeerSpot; none described a lasting change past one notice resolved, only that things were easy or accurate. Capterra and G2, where longer positive reviews live, returned 403."
      },
      "segments": ["seg:micro", "seg:smb", "seg:accountants"],
      "feature_ref": "feat:payroll",
      "cites": ["src:1", "src:2", "src:3", "src:4", "src:5", "src:6", "src:7", "src:30"]
    },
    {
      "id": "pain:late-direct-deposit",
      "statement": "I submitted payroll on time and my people still did not get paid on Friday.",
      "element": "b2b:ease_of_doing_business:stability",
      "shape": {
        "surface": "Direct deposits land late in the day, days late, or not at all, even when payroll was submitted before the deadline.",
        "operational": "The owner covers wages out of the register or their own pocket, fields angry staff, and loses hourly workers who need the money that morning.",
        "personal": "For the employee it is rent: 'IM ABOUT TO GET EVICTED FROM MY APARTMENT BECAUSE OF LACK OF PAYMENT.' For the owner it is trust with their own team."
      },
      "workflow": "Owner runs payroll in Gusto ahead of the cutoff; on payday employees check their bank app (often Chime or a prepaid card that normally pays early) and the deposit is not there; employee messages the owner, owner opens a Gusto chat.",
      "type": "felt",
      "confidence": "high",
      "priority": 2,
      "felt_evidence": {
        "kind": "switching",
        "what": "An owner whose staff were paid late into Friday moved back to ADP within months; others are paying staff from the cash register to cover the gap.",
        "cites": ["src:11", "src:8"]
      },
      "revealed_by": null,
      "triggers": [
        {"event": "Payday arrives and direct deposits are missing despite on-time submission.", "cites": ["src:8", "src:12"]},
        {"event": "Employees on early-pay banking apps notice they are paid later than with the old provider.", "cites": ["src:11"]},
        {"event": "A deposit shows confirmed but never arrives.", "cites": ["src:10"]}
      ],
      "who_feels": ["economic_buyer", "end_user"],
      "by_role": {
        "economic_buyer": {
          "says": [
            {"situation": "when_it_bites", "verbatim": "none of my baristas got their direct deposits.", "cites": ["src:8"]},
            {"situation": "venting", "verbatim": "Unreliable and stressful to deal with.", "cites": ["src:8"]},
            {"situation": "when_comparing", "verbatim": "I hurried up and switched back to ADP never had this issue with them and my people was happy", "cites": ["src:11"]},
            {"situation": "venting", "verbatim": "Even if payroll is in at the specified time direct deposits are rarely in on time!", "cites": ["src:12"]}
          ],
          "costs_them": "Cash pulled from the business to pay staff by hand, and goodwill with hourly workers who live paycheck to paycheck.",
          "fears": "Losing staff, or a wage claim, because the paycheck did not show up.",
          "dream_outcome": "Every employee sees the money in the morning, every payday, with no texts to the owner."
        },
        "end_user": {
          "says": [
            {"situation": "when_it_bites", "verbatim": "My paycheck is late and they say there is nothing wrong, but it will be deposited by 7 PM CT.", "cites": ["src:9"]},
            {"situation": "venting", "verbatim": "IM ABOUT TO GET EVICTED FROM MY APARTMENT BECAUSE OF LACK OF PAYMENT.", "cites": ["src:10"]},
            {"situation": "when_it_bites", "verbatim": "but gusto paid them late into friday, most of them need there money and to me a delay is a denial", "cites": ["src:11"]}
          ],
          "costs_them": "Late fees, overdrafts, rent they cannot cover on time.",
          "fears": "Missing rent or bills because the money did not land.",
          "dream_outcome": "Paid at midnight, every time, without having to ask anyone."
        }
      },
      "relief": {
        "line": "Paid by midnight. The deposit is there when they wake up, every payday.",
        "says": [
          {"role": "end_user", "verbatim": "every other paycheck was deposited by midnight without fail", "cites": ["src:9"]}
        ],
        "gap": null
      },
      "euphoria": {
        "line": "Payday is a non-event. Nobody on the team ever asks the owner where their money is.",
        "says": [],
        "gap": "No reviewer described this past state; Trustpilot positives speak to ease of running payroll, not to staff never chasing pay. Reddit, where employees talk about pay timing, could not be fetched."
      },
      "segments": ["seg:micro", "seg:smb"],
      "feature_ref": "feat:payroll",
      "cites": ["src:8", "src:9", "src:10", "src:11", "src:12"]
    },
    {
      "id": "pain:support-cannot-fix",
      "statement": "When something actually breaks, I get a chatbot or a rep who can only pass messages along, and nobody with authority ever fixes it.",
      "element": "b2b:ease_of_doing_business:responsiveness",
      "shape": {
        "surface": "Support is AI chat or reps who escalate, repeat questions, give conflicting answers and close cases without a fix.",
        "operational": "Every serious issue (tax notice, wrong W-2, benefits error) turns into weeks of tickets while the deadline that caused it keeps running.",
        "personal": "Hours lost every pay period and the sense of being alone with a problem that touches their legal liability: 'there is no supervisor to talk to.'"
      },
      "workflow": "Admin opens Gusto's in-app chat or support ticket about a payroll or tax problem, gets an AI answer or a rep who escalates to a specialist team, then waits days for email follow-up, often restarting the story with each new rep.",
      "type": "felt",
      "confidence": "high",
      "priority": 3,
      "felt_evidence": {
        "kind": "switching",
        "what": "A 20-person COO with seven open tickets wrote 'We are leaving. Actively.'; a weekly-payroll owner says the next unresolved issue is the day they switch.",
        "cites": ["src:16", "src:14"]
      },
      "revealed_by": null,
      "triggers": [
        {"event": "A problem that needs a human with authority (a tax correction, a payroll edit the system blocks).", "cites": ["src:13", "src:24"]},
        {"event": "A case is escalated and comes back with a different answer from a different rep.", "cites": ["src:15", "src:7"]}
      ],
      "who_feels": ["economic_buyer", "champion"],
      "by_role": {
        "economic_buyer": {
          "says": [
            {"situation": "venting", "verbatim": "The support reps function strictly as a go-between, passing messages back and forth", "cites": ["src:13"]},
            {"situation": "when_it_bites", "verbatim": "Their system prevents you from correcting your own payroll, forcing you to contact customer support.", "cites": ["src:24"]},
            {"situation": "when_refusing", "verbatim": "That may be the day I need to switch to another payroll service.", "cites": ["src:14"]},
            {"situation": "venting", "verbatim": "the support has been virtually nonexistent, with no real ownership or resolution.", "cites": ["src:29"]}
          ],
          "costs_them": "Owner time spent re-explaining the same issue, and fines that grow while the ticket sits.",
          "fears": "That a problem with legal weight never gets resolved before the agency deadline.",
          "dream_outcome": "One named person who knows payroll, owns the problem and closes it."
        },
        "champion": {
          "says": [
            {"situation": "venting", "verbatim": "They just pass me from person to person and each person says they will escalate it.", "cites": ["src:7"]},
            {"situation": "venting", "verbatim": "Repeatedly asking the customer to explain the same problem is not effective follow-through.", "cites": ["src:15"]},
            {"situation": "when_it_bites", "verbatim": "support gave me canned answers and passed me between three different reps.", "cites": ["src:8"]}
          ],
          "costs_them": "The person running payroll becomes a full-time case manager for the vendor.",
          "fears": "Having to tell the owner it is still not fixed.",
          "dream_outcome": "Ask once, get it fixed, move on."
        }
      },
      "relief": {
        "line": "A human who knows payroll. Get someone on the line who fixes it in one conversation.",
        "says": [],
        "gap": "Searched Trustpilot pages 1-5 and PeerSpot; positive reviews praise the product ('the program works well, when it works') but none quotes a support fix. G2 has a reviewer reportedly praising polite phone staff, but G2 returned 403."
      },
      "euphoria": {
        "line": "I trust the vendor. Problems are rare and when they happen I already know they will be handled.",
        "says": [],
        "gap": "No source found; would need G2, Capterra or Reddit, all blocked."
      },
      "segments": ["seg:micro", "seg:smb", "seg:accountants"],
      "feature_ref": null,
      "feature_note": "No feature in brain/company covers this. What kills it is a named, US-based payroll and tax specialist with authority to correct filings and payroll, reachable by phone.",
      "cites": ["src:7", "src:8", "src:13", "src:14", "src:15", "src:16", "src:24", "src:29"]
    },
    {
      "id": "pain:benefits-mishandled",
      "statement": "My employees' dental and vision got cancelled and nobody told me until my people did.",
      "element": "b2b:ease_of_doing_business:transparency",
      "shape": {
        "surface": "Coverage is dropped or mis-set, FSA cards fail, claims go unpaid, and the provider contacts employees before the owner.",
        "operational": "The owner has to restore coverage, field employee questions and fix plan settings while support tickets sit open.",
        "personal": "Embarrassment in front of the team they are trying to take care of, and fear for an employee mid-treatment."
      },
      "workflow": "Benefits are administered inside Gusto alongside payroll; a policy or plan change (or a carrier sync) silently changes coverage, and the owner learns about it from an employee or a denied claim.",
      "type": "felt",
      "confidence": "medium",
      "priority": 4,
      "felt_evidence": {
        "kind": "switching",
        "what": "A COO running a 20-person company is leaving after Gusto cancelled dental and vision without notice; another owner is demanding coverage be restored.",
        "cites": ["src:16", "src:17"]
      },
      "revealed_by": null,
      "triggers": [
        {"event": "An employee reports coverage is gone or a claim was denied.", "cites": ["src:16", "src:17"]},
        {"event": "Editing a time-off or plan setting changes something else without warning.", "cites": ["src:16"]}
      ],
      "who_feels": ["economic_buyer", "end_user"],
      "by_role": {
        "economic_buyer": {
          "says": [
            {"situation": "venting", "verbatim": "Gusto had no plan to tell us. Ever.", "cites": ["src:16"]},
            {"situation": "when_it_bites", "verbatim": "Gusto messaged my employees directly without my knowledge or authorization.", "cites": ["src:16"]},
            {"situation": "venting", "verbatim": "Gusto overpromised, repeatedly mishandled our benefits, and has been painfully slow to fix the problems.", "cites": ["src:17"]},
            {"situation": "when_refusing", "verbatim": "We are leaving. Actively.", "cites": ["src:16"]}
          ],
          "costs_them": "Trust with staff, and time spent rebuilding coverage they already paid for.",
          "fears": "An employee uninsured during a medical event, and looking like an employer who does not care.",
          "dream_outcome": "Benefits that just stay on, with any change shown to the owner first."
        },
        "end_user": {
          "says": [
            {"situation": "when_it_bites", "verbatim": "I want Gusto to restore dental and vision coverage or provide immediate replacement options for my approval.", "cites": ["src:17"]}
          ],
          "costs_them": "Out-of-pocket medical bills and uncertainty about whether they are covered.",
          "fears": "Being uninsured without knowing it.",
          "dream_outcome": "Coverage they never have to check on."
        }
      },
      "relief": {
        "line": "Nothing changes without me. Any change to coverage shows up for the owner before it reaches the team.",
        "says": [],
        "gap": "No positive benefits quote found on Trustpilot or PeerSpot; Capterra and G2 returned 403."
      },
      "euphoria": {
        "line": "Benefits that help me keep people. The team sees real coverage as a reason to stay.",
        "says": [],
        "gap": "Not found in any read source. TriNet's survey shows the stake (23% lost staff over benefits) but no buyer described reaching this state."
      },
      "segments": ["seg:smb"],
      "feature_ref": "feat:benefits",
      "cites": ["src:16", "src:17", "src:27"]
    },
    {
      "id": "pain:accountant-errors-multiply",
      "statement": "When I run payroll for a dozen clients, one provider mistake becomes a dozen notices, and support cannot even tell which of my companies I am talking about.",
      "element": "b2b:functional:scalability",
      "shape": {
        "surface": "Errors repeat across every client company the accountant manages; support asks 'which company?'; journal entries land in accounts the client's books do not use.",
        "operational": "The firm does the correction and reconciliation work for each client by hand, unbilled, and remaps payroll entries in QuickBooks Online.",
        "personal": "Their reputation with every client rides on the vendor they picked; one bad quarter puts all of it at risk."
      },
      "workflow": "Accountant or bookkeeper logs into each client's Gusto account (or the accountant view), runs payroll, lets Gusto sync the journal entry to QuickBooks Online, and handles state filings and notices for every client.",
      "type": "felt",
      "confidence": "medium",
      "priority": 5,
      "felt_evidence": {
        "kind": "switching",
        "what": "A CPA who runs payroll for client businesses on Gusto is moving every client to ADP after a billing error support could not trace to the right account.",
        "cites": ["src:18", "src:19"]
      },
      "revealed_by": null,
      "triggers": [
        {"event": "A quarterly filing error hits every client at once.", "cites": ["src:6"]},
        {"event": "Payroll journal entries sync to QuickBooks Online into the wrong accounts.", "cites": ["src:25"]},
        {"event": "Support cannot locate the right client account in a multi-company setup.", "cites": ["src:18"]}
      ],
      "who_feels": ["champion", "technical_evaluator"],
      "by_role": {
        "champion": {
          "says": [
            {"situation": "venting", "verbatim": "Incorrect Q1 LNI filings with ALL the companies I manage, even after notifying them of issues before quarter ended.", "cites": ["src:6"]},
            {"situation": "when_refusing", "verbatim": "moving everyone to ADP and cancelling before the next billing cycle.", "cites": ["src:18"]},
            {"situation": "venting", "verbatim": "Billing errors + broken support = unreliable payroll processor.", "cites": ["src:19"]}
          ],
          "costs_them": "Unbilled hours per client per incident, and the risk of losing clients who blame the firm.",
          "fears": "A client relationship ending over a vendor's mistake.",
          "dream_outcome": "Recommend one payroll tool to every client and never have to apologize for it."
        },
        "technical_evaluator": {
          "says": [
            {"situation": "when_comparing", "verbatim": "every single account for a deduction went to a liability account, but not a lot of businesses run that way.", "cites": ["src:25"]}
          ],
          "costs_them": "Manual remapping after each payroll sync before books can close.",
          "fears": "Books that do not tie out at month end.",
          "dream_outcome": "Payroll that lands in the client's chart of accounts the way they already run it."
        }
      },
      "relief": {
        "line": "Accurate for every client. The tool is quick and right across the whole book of clients.",
        "says": [
          {"role": "champion", "verbatim": "Gusto has been attentive, helpful, quick, and accurate for me", "cites": ["src:28"]}
        ],
        "gap": null
      },
      "euphoria": {
        "line": "My standard stack. Every new client gets moved onto it because it makes the firm look good.",
        "says": [
          {"role": "champion", "verbatim": "As I bring on clients I insist they switch to Gusto if they are with a different processor.", "cites": ["src:28"]}
        ],
        "gap": null
      },
      "segments": ["seg:accountants"],
      "feature_ref": null,
      "feature_note": "brain/company lists no accountant-facing feature. What kills it is a multi-client view with per-client filing status and QuickBooks Online account mapping the firm controls.",
      "cites": ["src:6", "src:18", "src:19", "src:25", "src:28"]
    },
    {
      "id": "pain:surprise-billing",
      "statement": "The price changed or kept charging after I cancelled, and getting it reversed took a month.",
      "element": "b2b:table_stakes:acceptable_price",
      "shape": {
        "surface": "Monthly rate doubles without notice, promos lapse into charges, billing continues after suspension or cancellation.",
        "operational": "Owner disputes charges by email and chat for weeks; in one case suspending the account also stopped quarterly filings.",
        "personal": "Feeling tricked by a vendor holding their bank account access, which erodes trust in everything else it does."
      },
      "workflow": "Owner reviews the bank statement or Gusto invoice, finds a higher or unexpected charge, emails or chats support, and waits for a refund while the next bill comes.",
      "type": "felt",
      "confidence": "medium",
      "priority": 6,
      "felt_evidence": {
        "kind": "switching",
        "what": "A CPA is moving all clients off after a $184 surprise charge; another owner suspended the account to stop double charges.",
        "cites": ["src:18", "src:20"]
      },
      "revealed_by": null,
      "triggers": [
        {"event": "A promotional rate ends or the plan price changes without notice.", "cites": ["src:18", "src:20"]},
        {"event": "The business suspends or cancels and charges continue.", "cites": ["src:20"]}
      ],
      "who_feels": ["economic_buyer"],
      "by_role": {
        "economic_buyer": {
          "says": [
            {"situation": "venting", "verbatim": "Doubled my monthly rate without notice.", "cites": ["src:20"]},
            {"situation": "when_it_bites", "verbatim": "Gusto billed me $184 with no advance notice", "cites": ["src:18"]},
            {"situation": "when_looking", "verbatim": "read the billing terms closely and test their support before you commit.", "cites": ["src:18"]},
            {"situation": "when_it_bites", "verbatim": "they failed to file TWC for Q1 because I suspended my account", "cites": ["src:20"]}
          ],
          "costs_them": "Overcharges, time disputing them, and in one case a missed state filing.",
          "fears": "That the vendor with access to their bank account will keep pulling money.",
          "dream_outcome": "One flat price they can predict, and a clean exit if they leave."
        }
      },
      "relief": {
        "line": "The bill I expected. Price stays what I signed up for.",
        "says": [],
        "gap": "brenda dye mentions 'The low price helps as well' but not predictability; no reviewer described relief from billing surprises."
      },
      "euphoria": {
        "line": "Never look at the payroll bill. It is a fixed cost that does not need watching.",
        "says": [],
        "gap": "Not found in any read source."
      },
      "segments": ["seg:micro", "seg:accountants"],
      "feature_ref": null,
      "feature_note": "Not a product feature in brain/company. What kills it is billing changes shown in advance and cancellation that stops charges but keeps filings until the account is handed off.",
      "cites": ["src:18", "src:20"]
    },
    {
      "id": "pain:payroll-blocked",
      "statement": "They blocked my payroll after the deadline over a funding check, so my people were not paid and I still got the fee.",
      "element": "b2b:ease_of_doing_business:decreased_hassles",
      "shape": {
        "surface": "Payroll is held or blocked for insufficient funds or verification after submission, or debited twice when the owner already wired funds.",
        "operational": "The owner scrambles to re-fund or pay by hand after the cutoff has passed.",
        "personal": "Panic on payday, and paying a fee for a service that did not run."
      },
      "workflow": "Owner submits payroll in Gusto; Gusto's funding check holds or blocks it after the submission deadline, or debits the bank account even though a wire was sent.",
      "type": "felt",
      "confidence": "medium",
      "priority": 7,
      "felt_evidence": {
        "kind": "complaining",
        "what": "Three dated Trustpilot complaints between June and October 2026 describe blocked payroll or double collection.",
        "cites": ["src:21", "src:22", "src:23"]
      },
      "revealed_by": null,
      "triggers": [
        {"event": "Gusto's risk check flags the account after payroll is submitted.", "cites": ["src:21", "src:23"]},
        {"event": "Owner wires payroll funds and Gusto also debits the bank.", "cites": ["src:22"]}
      ],
      "who_feels": ["economic_buyer"],
      "by_role": {
        "economic_buyer": {
          "says": [
            {"situation": "venting", "verbatim": "They will block your payroll after the submission deadline", "cites": ["src:21"]},
            {"situation": "when_it_bites", "verbatim": "Even though we made the wire to make the payroll payment, they collected the money from our bank account", "cites": ["src:22"]},
            {"situation": "venting", "verbatim": "They blocked my payroll anyway, therefore did not render any services.", "cites": ["src:23"]}
          ],
          "costs_them": "Fees, double-debited cash, and staff paid late.",
          "fears": "Payday failing with no warning and no way to fix it in time.",
          "dream_outcome": "Any funding issue flagged before the deadline, with time to fix it."
        }
      },
      "relief": {
        "line": "Warned in time. Funding problems surface before cutoff, not after.",
        "says": [],
        "gap": "No reviewer described this resolved; searched Trustpilot pages 1-5."
      },
      "euphoria": {
        "line": "Payroll that never stalls. Submitting means paid.",
        "says": [],
        "gap": "Not found."
